create table "ddl_people" ("id" bigint generated by default as identity primary key, "name" varchar(255) not null);
create table "ddl_kinds" ("kind_id" bigint generated by default as identity primary key, "label" varchar(40) not null, "body" text not null, "count" integer not null, "big" bigint not null, "ratio" double precision not null, "price" numeric(8, 2) not null, "exact" numeric(12, 4) not null, "flag" boolean not null, "meta" jsonb not null, "token" uuid not null, "blob" bytea not null, "day" date not null, "at" timestamptz(3) not null);
create table "ddl_modifiers" ("id" uuid default (encode(set_bit(set_bit(overlay(uuid_send(gen_random_uuid()) placing substring(int8send(floor(extract(epoch from clock_timestamp()) * 1000)::bigint) from 3) from 1 for 6), 52, 1), 53, 1), 'hex')::uuid) primary key, "email" varchar(255) not null, "nickname" varchar(255), "role" varchar(255) default 'member' not null, "level" integer default 1 not null, "active" boolean default true not null, "settings" jsonb default '{}' not null, "password" varchar(255) not null, "api_key" varchar(255), "public_id" uuid default (encode(set_bit(set_bit(overlay(uuid_send(gen_random_uuid()) placing substring(int8send(floor(extract(epoch from clock_timestamp()) * 1000)::bigint) from 3) from 1 for 6), 52, 1), 53, 1), 'hex')::uuid) not null, "seen_at" timestamptz(3) default now(), "created_at" timestamptz(3) default now() not null, "updated_at" timestamptz(3) default now() not null, "deleted_at" timestamptz(3));
create unique index "ddl_modifiers_email_unique" on "ddl_modifiers" ("email");
create unique index "ddl_modifiers_api_key_unique" on "ddl_modifiers" ("api_key");
create unique index "ddl_modifiers_public_id_unique" on "ddl_modifiers" ("public_id");
create table "ddl_categories" ("id" bigint generated by default as identity primary key, "title" varchar(255) not null);
create table "ddl_codes" ("code" varchar(255) primary key, "title" varchar(255) not null);
create table "ddl_keys" ("id" bigint generated by default as identity primary key, "person_id" bigint not null references "ddl_people" ("id") on delete cascade, "editor_id" bigint references "ddl_people" ("id") on delete set null, "owner_id" bigint not null references "ddl_people" ("id") on delete restrict, "plain_id" bigint not null references "ddl_people" ("id"), "modifier_id" uuid references "ddl_modifiers" ("id") on delete cascade, "loose_id" bigint not null, "ddl_category_id" bigint not null references "ddl_categories" ("id"));
